2	import type { ChecklistItem, Pack } from "@runlog/rules-schema";
3	import type { RunState } from "@runlog/engine";
4	import { allMade, evidenceFor, pointMade, pointOf, rowMade, type Settling, type Shown } from "./evidence.ts";
5	
6	/**
7	 * Whether the list leaves a row out.
8	 *
9	 * What is already in front of the player as a rule is not listed again
10	 * under a box; a point with nothing left to list has nothing to ask, and
11	 * the rule it stands for is doing the asking.
12	 *
13	 * Only where something can actually answer it, though: the game settling
14	 * it, or the rule carrying the tick that honors it. A row nothing can
15	 * answer stays on the screen whatever it is told, because the alternative
16	 * is a step that cannot be finished.
17	 *
18	 * One spelling, because the answer decides two things that have to agree:
19	 * which rows the card draws, and which box the tick on such a row comes
20	 * from -- the rule's, which carries no tally.
21	 */
22	function offTheList(s: Shown, settling?: Settling): boolean {
23	  const answerable = Boolean(settling && (settling.owing(s) || settling.settled(s) || settling.answered?.(s)));
24	  return Boolean(settling?.hidden?.(s) && answerable);
25	}
26	
27	/**
28	 * Points to tick off, with their evidence under them.
29	 *
30	 * A point that shows a table's results lists them beneath it, each with a box
31	 * of its own; ticking them all ticks the point, and ticking the point ticks
32	 * them all. The parent's box is what the point reads as, the children are
33	 * what it is about. A point with nothing to show is a plain box.
34	 *
35	 * A point that shows a table the unit never rolled on is not shown at all:
36	 * there is nothing to make a promise about, and a box that must be ticked
37	 * beside "nothing on the table" is a box that teaches people to tick
38	 * without reading. An optional point is shown, and the step does not wait
39	 * for it. A point with a tally counts its ticks.
40	 *
41	 * The ticked set is the step's and lives in the log, so a reload keeps it.
42	 *
43	 * What the boxes are for used to be written out over every list: the app
44	 * cannot see the work, it only records that you did it. It is the premise
45	 * of the whole thing, said once in the guide and on the welcome page, and
46	 * printing it above every step read as a machine that did not trust the
47	 * person using it. The list carries it as its title instead, for whoever
48	 * wonders.
49	 */
50	export function Checklist({
51	  items,
52	  pack,
53	  state,
54	  ticked,
55	  onToggle,
56	  settling,
57	  action,
58	}: {
59	  items: ChecklistItem[];
60	  pack: Pack;
61	  state: RunState;
62	  ticked: Set<string>;
63	  onToggle: (keys: string[], on: boolean, tally?: string) => void;
64	  /** Which rows the game settles itself, and whether it has; see evidence.ts. */
65	  settling?: Settling;
66	  /** The move a row is waiting on, drawn on the row rather than in a panel of its own. */
67	  action?: (s: Shown) => ReactNode;
68	}) {
69	  const points = useMemo(() => items.map(pointOf), [items]);
70	  const evidence = useMemo(() => points.map((p) => (p.shows ? evidenceFor(pack, state, p.shows) : [])), [points, pack, state]);
71	
72	  return (
73	    <ul
74	      className="checklist"
75	      title="Nothing here is checked by the app. It cannot see the work; ticking a box is your word, and the log keeps it."
76	    >
77	      {points.map((point, i) => {
78	        const shown: Shown[] = evidence[i] ?? [];
79	        if (point.shows && shown.length === 0) return null;
80	        const listed = shown.filter((s) => !offTheList(s, settling));
81	        if (point.shows && listed.length === 0) return null;
82	        // A row the game settles is not offered as a box to tick, and
83	        // ticking the point over it does not reach down to it.
84	        const mine = listed.filter((s) => !settling?.owing(s) && !settling?.settled(s));
85	        const childKeys = mine.map((s) => `${i}:${s.key}`);
86	        const made = pointMade(i, shown, ticked, point, settling);
87	        const toggle = (keys: string[], on: boolean) =>
88	          onToggle(
89	            keys.filter((k) => ticked.has(k) !== on),
90	            on,
91	            point.tally,
92	          );
93	        return (
94	          <li key={i}>
95	            <label>
96	              <input
97	                type="checkbox"
98	                checked={made}
99	                disabled={listed.length > 0 && childKeys.length === 0}
100	                onChange={(e) => toggle(shown.length > 0 ? childKeys : [`${i}`], e.target.checked)}
101	              />
102	              <span>
103	                {point.text}
104	                {point.optional && <span className="chip skip">optional</span>}
105	              </span>
106	            </label>
107	            {listed.length > 0 && (
108	              <ul className="evidence">
109	                {listed.map((s) => {
110	                  const key = `${i}:${s.key}`;
111	                  const theirs = Boolean(settling?.owing(s) || settling?.settled(s));
112	                  return (
113	                    <li key={key} className={theirs ? "settling" : ""}>
114	                      <label>
115	                        <input
116	                          type="checkbox"
117	                          checked={rowMade(key, s, ticked, settling)}
118	                          disabled={theirs}
119	                          title={theirs ? "The game settles this one: it is honored by the roll it asks for, not by saying so." : undefined}
120	                          onChange={(e) => toggle([key], e.target.checked)}
121	                        />
122	                        <span>
123	                          <span className="where">{s.where}</span>
124	                          {s.text}
125	                        </span>
126	                      </label>
127	                      {settling?.owing(s) && action?.(s)}
128	                    </li>
129	                  );
130	                })}
131	              </ul>
132	            )}
133	          </li>
134	        );
135	      })}
136	    </ul>
137	  );
138	}
139	
140	/** Whether every point that must be made is made, for the button that waits on it. */
141	export function checklistDone(items: ChecklistItem[], pack: Pack, state: RunState, ticked: Set<string>, settling?: Settling): boolean {
142	  const points = items.map(pointOf);
143	  return allMade(
144	    points,
145	    points.map((p) => (p.shows ? evidenceFor(pack, state, p.shows) : [])),
146	    ticked,
147	    settling,
148	  );
149	}
150	
151	/**
152	 * The boxes a step is still waiting on, for a press that means "all of them".
153	 *
154	 * The page's own box is the authority on which keys a tick writes -- a
155	 * point with evidence writes its children, a plain one writes itself --
156	 * so this reads the same `pointOf`/`evidenceFor`/`pointMade` machinery
157	 * rather than a second copy of the rules. Optional points are left alone,
158	 * because the step is not waiting on them, and nothing here unticks.
159	 *
160	 * Grouped by tally, because a group is one `check()` and a counter moves
161	 * by the size of the group it is given: two points on the same counter are
162	 * one call of two boxes, which is what ticking them one at a time adds up
163	 * to. A row the list leaves out is grouped away from the point's tally,
164	 * because the box that ticks it is the rule's own and that one carries no
165	 * counter; put in the point's group it would move the counter further than
166	 * any run of clicks could. A row the game itself settles is in no group;
167	 * one it still owes is not tickable at all, so the list comes back short
168	 * and the step stays unfinished, which is the answer.
169	 */
170	export function ticksToFinish(
171	  items: ChecklistItem[],
172	  pack: Pack,
173	  state: RunState,
174	  ticked: Set<string>,
175	  settling?: Settling,
176	): Array<{ items: string[]; tally?: string }> {
177	  const groups = new Map<string, { items: string[]; tally?: string }>();
178	  const add = (tally: string | undefined, keys: string[]) => {
179	    const fresh = keys.filter((k) => !ticked.has(k));
180	    if (fresh.length === 0) return;
181	    const group = groups.get(tally ?? "") ?? { items: [], ...(tally ? { tally } : {}) };
182	    group.items.push(...fresh);
183	    groups.set(tally ?? "", group);
184	  };
185	  items.map(pointOf).forEach((point, i) => {
186	    if (point.optional) return;
187	    const shown = point.shows ? evidenceFor(pack, state, point.shows) : [];
188	    if (pointMade(i, shown, ticked, point, settling)) return;
189	    if (shown.length === 0) {
190	      add(point.tally, [`${i}`]);
191	      return;
192	    }
193	    // A row the game settles is not offered as a box to tick, and ticking
194	    // the point over it does not reach down to it.
195	    const mine = shown.filter((s) => !settling?.owing(s) && !settling?.settled(s));
196	    const keysOf = (rows: Shown[]) => rows.map((s) => `${i}:${s.key}`);
197	    add(point.tally, keysOf(mine.filter((s) => !offTheList(s, settling))));
198	    add(undefined, keysOf(mine.filter((s) => offTheList(s, settling))));
199	  });
200	  return [...groups.values()];
201	}
