 *
 * What the boxes are for used to be written out over every list: the app
 * cannot see the work, it only records that you did it. It is the premise
 * of the whole thing, said once in the guide and on the welcome page, and
 * printing it above every step read as a machine that did not trust the
 * person using it. The list carries it as its title instead, for whoever
 * wonders.
 */
export function Checklist({
  items,
  pack,
  state,
  ticked,
  onToggle,
  settling,
  action,
}: {
  items: ChecklistItem[];
  pack: Pack;
  state: RunState;
  ticked: Set<string>;
  onToggle: (keys: string[], on: boolean, tally?: string) => void;
  /** Which rows the game settles itself, and whether it has; see evidence.ts. */
  settling?: Settling;
  /** The move a row is waiting on, drawn on the row rather than in a panel of its own. */
  action?: (s: Shown) => ReactNode;
}) {
  const points = useMemo(() => items.map(pointOf), [items]);
  const evidence = useMemo(() => points.map((p) => (p.shows ? evidenceFor(pack, state, p.shows) : [])), [points, pack, state]);

  return (
    <ul
      className="checklist"
      title="Nothing here is checked by the app. It cannot see the work; ticking a box is your word, and the log keeps it."
    >
      {points.map((point, i) => {
        const shown: Shown[] = evidence[i] ?? [];
        if (point.shows && shown.length === 0) return null;
        const listed = shown.filter((s) => !offTheList(s, settling));
        if (point.shows && listed.length === 0) return null;
        // A row the game settles is not offered as a box to tick, and
        // ticking the point over it does not reach down to it.
        const mine = listed.filter((s) => !settling?.owing(s) && !settling?.settled(s));
        const childKeys = mine.map((s) => `${i}:${s.key}`);
        const made = pointMade(i, shown, ticked, point, settling);
        const toggle = (keys: string[], on: boolean) =>
          onToggle(
            keys.filter((k) => ticked.has(k) !== on),
            on,
            point.tally,
          );
        return (
          <li key={i}>
            <label>
              <input
                type="checkbox"
                checked={made}
                disabled={listed.length > 0 && childKeys.length === 0}
                onChange={(e) => toggle(shown.length > 0 ? childKeys : [`${i}`], e.target.checked)}
              />
              <span>
                {point.text}
                {point.optional && <span className="chip skip">optional</span>}
              </span>
            </label>
            {listed.length > 0 && (
              <ul className="evidence">
                {listed.map((s) => {
                  const key = `${i}:${s.key}`;
                  const theirs = Boolean(settling?.owing(s) || settling?.settled(s));
                  return (
                    <li key={key} className={theirs ? "settling" : ""}>
                      <label>
                        <input
                          type="checkbox"
                          checked={rowMade(key, s, ticked, settling)}
                          disabled={theirs}
                          title={theirs ? "The game settles this one: it is honored by the roll it asks for, not by saying so." : undefined}
                          onChange={(e) => toggle([key], e.target.checked)}
                        />
                        <span>
                          <span className="where">{s.where}</span>
                          {s.text}
                        </span>
                      </label>
                      {settling?.owing(s) && action?.(s)}
                    </li>
                  );
                })}
              </ul>
            )}
          </li>
        );
      })}
    </ul>
  );
}

/** Whether every point that must be made is made, for the button that waits on it. */
export function checklistDone(items: ChecklistItem[], pack: Pack, state: RunState, ticked: Set<string>, settling?: Settling): boolean {
  const points = items.map(pointOf);
  return allMade(
    points,
    points.map((p) => (p.shows ? evidenceFor(pack, state, p.shows) : [])),
    ticked,
    settling,
  );
}

/**
 * The boxes a step is still waiting on, for a press that means "all of them".
 *
 * The page's own box is the authority on which keys a tick writes -- a
 * point with evidence writes its children, a plain one writes itself --
 * so this reads the same `pointOf`/`evidenceFor`/`pointMade` machinery
 * rather than a second copy of the rules. Optional points are left alone,
 * because the step is not waiting on them, and nothing here unticks.
 *
 * Grouped by tally, because a group is one `check()` and a counter moves
 * by the size of the group it is given: two points on the same counter are
 * one call of two boxes, which is what ticking them one at a time adds up
 * to. A row the list leaves out is grouped away from the point's tally,
 * because the box that ticks it is the rule's own and that one carries no
 * counter; put in the point's group it would move the counter further than
 * any run of clicks could. A row the game itself settles is in no group;
 * one it still owes is not tickable at all, so the list comes back short
 * and the step stays unfinished, which is the answer.
 */
export function ticksToFinish(
  items: ChecklistItem[],
  pack: Pack,
  state: RunState,
  ticked: Set<string>,
  settling?: Settling,
): Array<{ items: string[]; tally?: string }> {
  const groups = new Map<string, { items: string[]; tally?: string }>();
  const add = (tally: string | undefined, keys: string[]) => {
    const fresh = keys.filter((k) => !ticked.has(k));
    if (fresh.length === 0) return;
    const group = groups.get(tally ?? "") ?? { items: [], ...(tally ? { tally } : {}) };
    group.items.push(...fresh);
    groups.set(tally ?? "", group);
  };
  items.map(pointOf).forEach((point, i) => {
    if (point.optional) return;
    const shown = point.shows ? evidenceFor(pack, state, point.shows) : [];
    if (pointMade(i, shown, ticked, point, settling)) return;
    if (shown.length === 0) {
      add(point.tally, [`${i}`]);
      return;
    }
    // A row the game settles is not offered as a box to tick, and ticking
    // the point over it does not reach down to it.
    const mine = shown.filter((s) => !settling?.owing(s) && !settling?.settled(s));
    const keysOf = (rows: Shown[]) => rows.map((s) => `${i}:${s.key}`);
    add(point.tally, keysOf(mine.filter((s) => !offTheList(s, settling))));
    add(undefined, keysOf(mine.filter((s) => offTheList(s, settling))));
  });
  return [...groups.values()];
}
